    81  IFileReaderDevice* IFileReaderDevice::getReader(const std::string& fileName)
    82  {
    83          const auto extensionPos = fileName.find_last_of('.');
    84          const auto fileExtension = extensionPos != std::string::npos ? fileName.substr(extensionPos) : "";
    85
    86          if (fileExtension == ".pcapng" || fileExtension == ".zstd" || fileExtension == ".zst")
    87                  return new PcapNgFileReaderDevice(fileName);
    88          else if (fileExtension == ".snoop")
    89                  return new SnoopFileReaderDevice(fileName);
    90
    91          return new PcapFileReaderDevice(fileName);
    92  }
