   291  bool PcapFileReaderDevice::getNextPacket(RawPacket& rawPacket)
   292  {
   293          rawPacket.clear();
   294          if (m_PcapDescriptor == nullptr)
   295          {
   296                  PCPP_LOG_ERROR("File device '" << m_FileName << "' not opened");
   297                  return false;
   298          }
   299          pcap_pkthdr pkthdr;
   300          const uint8_t* pPacketData = pcap_next(m_PcapDescriptor, &pkthdr);
   301          if (pPacketData == nullptr)
   302          {
   303                  PCPP_LOG_DEBUG("Packet could not be read. Probably end-of-file");
   304                  return false;
   305          }
   306
   307          uint8_t* pMyPacketData = new uint8_t[pkthdr.caplen];
   308          memcpy(pMyPacketData, pPacketData, pkthdr.caplen);
   309  #if defined(PCAP_TSTAMP_PRECISION_NANO)
   310          timespec ts = { pkthdr.ts.tv_sec, static_cast<long>(pkthdr.ts.tv_usec) }; //because we opened with nano second precision 'tv_usec' is actually nanos
   311  #else
   312          struct timeval ts = pkthdr.ts;
   313  #endif
   314          if (!rawPacket.setRawData(pMyPacketData, pkthdr.caplen, ts, static_cast<LinkLayerType>(m_PcapLinkLayerType), pkthdr.len))
   315          {
   316                  PCPP_LOG_ERROR("Couldn't set data to raw packet");
   317                  return false;
   318          }
   319          m_NumOfPacketsRead++;
   320          return true;
   321  }
